// Normalizes input whether triggered by Schedule Trigger or POST Webhook
const isWebhook = $json.body !== undefined;
let topic = '';

if (isWebhook) {
  topic = typeof $json.body.topic === 'string' ? $json.body.topic.trim() : '';
} else {
  // Default topic for daily scheduled runs (configurable via env or fallback)
  topic = ($env.DEFAULT_RESEARCH_TOPIC || 'quantum computing').trim();
}

const isValid = topic.length > 0 && topic.length <= 200;

return [{
  json: {
    topic,
    trigger_source: isWebhook ? 'webhook' : 'schedule',
    is_valid: isValid,
    error: isValid ? null : 'Field "topic" must be a non-empty string with maximum 200 characters.'
  }
}];

// Safely parses RSS XML, sanitizes, deduplicates URLs, and picks top 5 newest articles
const rawXml = $json.data || '';
const topic = $('Normalize Topic & Trigger Source').first().json.topic;

function cleanText(str) {
  if (!str) return '';
  return str
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .trim();
}

const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/g;
let match;

while ((match = itemRegex.exec(rawXml)) !== null) {
  const block = match[1];
  const titleMatch = /<title>([\s\S]*?)<\/title>/.exec(block);
  const linkMatch = /<link>([\s\S]*?)<\/link>/.exec(block);
  const pubDateMatch = /<pubDate>([\s\S]*?)<\/pubDate>/.exec(block);
  const descMatch = /<description>([\s\S]*?)<\/description>/.exec(block);
  const sourceMatch = /<source[^>]*>([\s\S]*?)<\/source>/.exec(block);

  const rawTitle = titleMatch ? cleanText(titleMatch[1]) : '';
  const rawLink = linkMatch ? cleanText(linkMatch[1]) : '';
  const rawPubDate = pubDateMatch ? pubDateMatch[1].trim() : '';
  const rawDesc = descMatch ? cleanText(descMatch[1]) : '';
  const rawSource = sourceMatch ? cleanText(sourceMatch[1]) : 'Google News';

  // Strict validation: link must be valid http or https URL
  if (!rawLink || !/^https?:\/\//i.test(rawLink)) {
    continue;
  }
  if (!rawTitle) {
    continue;
  }

  let timestamp = 0;
  let isoDate = new Date().toISOString();
  if (rawPubDate) {
    const parsed = Date.parse(rawPubDate);
    if (!isNaN(parsed)) {
      timestamp = parsed;
      isoDate = new Date(parsed).toISOString();
    }
  }

  items.push({
    title: rawTitle,
    source_url: rawLink,
    published_at: isoDate,
    timestamp,
    description: rawDesc || rawTitle,
    source_name: rawSource,
    topic
  });
}

// Deduplicate by source_url
const seenUrls = new Set();
const uniqueItems = [];
for (const item of items) {
  if (!seenUrls.has(item.source_url)) {
    seenUrls.add(item.source_url);
    uniqueItems.push(item);
  }
}

// Sort newest first
uniqueItems.sort((a, b) => b.timestamp - a.timestamp);

// Keep at most 5 most recent valid articles
const top5 = uniqueItems.slice(0, 5);

if (top5.length === 0) {
  return [{
    json: {
      has_articles: false,
      articles: [],
      topic,
      count: 0
    }
  }];
}

// Return each article as a separate workflow item for processing
return top5.map((art, index) => ({
  json: {
    ...art,
    article_index: index + 1,
    total_articles: top5.length,
    has_articles: true
  }
}));

