// Validates Gemini structured output and enforces schema integrity
const originalArticle = $('Parse, Clean & Top 5 Articles').item.json;
const responseData = $json;

let parsed = null;
try {
  const rawCandidateText = responseData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawCandidateText) {
    // Strip potential markdown fences if present
    const cleaned = rawCandidateText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
    parsed = JSON.parse(cleaned);
  }
} catch (err) {
  parsed = null;
}

// Strict schema validation checks
const hasValidTitle = parsed && typeof parsed.title === 'string' && parsed.title.trim().length > 0;
const hasValidSummary = parsed && typeof parsed.summary === 'string' && parsed.summary.trim().length > 0;
const hasValidKeyPoints = parsed && Array.isArray(parsed.key_points) && parsed.key_points.length > 0;
const isUrlMatched = parsed && parsed.source_url === originalArticle.source_url;

let validatedSummary;
if (hasValidTitle && hasValidSummary && hasValidKeyPoints && isUrlMatched) {
  validatedSummary = {
    title: parsed.title.trim(),
    summary: parsed.summary.trim(),
    key_points: parsed.key_points.map(k => String(k).trim()).filter(Boolean),
    source_url: originalArticle.source_url
  };
} else {
  // Resilient fallback to preserve pipeline execution on non-standard model replies
  validatedSummary = {
    title: originalArticle.title,
    summary: originalArticle.description || 'Summary unavailable based on available RSS feed snippet.',
    key_points: [
      'Extracted from publisher feed',
      'Full article requires direct publisher consultation'
    ],
    source_url: originalArticle.source_url
  };
}

return [{
  json: {
    ...validatedSummary,
    topic: originalArticle.topic,
    published_at: originalArticle.published_at,
    source_name: originalArticle.source_name,
    article_index: originalArticle.article_index,
    total_articles: originalArticle.total_articles
  }
}];

