// Prepare Pinecone upsert payload with deterministic ID based on canonical URL SHA-256
let crypto;
try {
  crypto = require('crypto');
} catch (e) {
  crypto = null;
}

const article = $('Validate Gemini Output').item.json;
const embeddingResponse = $json;

const vectorValues = embeddingResponse.embedding?.values || [];

let deterministicId;
if (crypto && typeof crypto.createHash === 'function') {
  deterministicId = crypto.createHash('sha256').update(article.source_url).digest('hex');
} else {
  // Deterministic 64-char hex hash fallback
  let h1 = 0xdeadbeef ^ article.source_url.length;
  let h2 = 0x41c6ce57 ^ article.source_url.length;
  let h3 = 0x9e3779b9;
  let h4 = 0x5a827999;
  for (let i = 0; i < article.source_url.length; i++) {
    const ch = article.source_url.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
    h3 = Math.imul(h3 ^ ch, 2246822507);
    h4 = Math.imul(h4 ^ ch, 3266489909);
  }
  const toHex = (n) => (n >>> 0).toString(16).padStart(8, '0');
  deterministicId = toHex(h1) + toHex(h2) + toHex(h3) + toHex(h4) + toHex(~h4) + toHex(~h3) + toHex(~h2) + toHex(~h1);
}

return [{
  json: {
    vector_id: deterministicId,
    values: vectorValues,
    metadata: {
      title: article.title,
      summary: article.summary,
      key_points: article.key_points,
      source_url: article.source_url,
      topic: article.topic,
      published_at: article.published_at,
      source_name: article.source_name
    },
    article_data: article
  }
}];

