// Aggregate all processed articles and construct an XSS-safe HTML email digest
const allArticles = $('Prepare Pinecone Vector & Hash').all().map(item => item.json.article_data);
const firstItem = allArticles[0] || {};
const topic = firstItem.topic || 'General AI Research';
const dateStr = new Date().toLocaleDateString('en-US', { dateStyle: 'full' });

function escapeHtml(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

let articlesHtml = '';
allArticles.forEach((art, idx) => {
  const safeTitle = escapeHtml(art.title);
  const safeSummary = escapeHtml(art.summary);
  const safeUrl = encodeURI(art.source_url);
  const safeSource = escapeHtml(art.source_name || 'Publisher');

  const pointsList = (art.key_points || [])
    .map(pt => `<li>${escapeHtml(pt)}</li>`)
    .join('');

  articlesHtml += `
    <div style="margin-bottom: 24px; padding: 18px; border: 1px solid #e2e8f0; border-radius: 8px; background: #ffffff;">
      <h3 style="margin-top: 0; margin-bottom: 8px; color: #1a202c; font-size: 18px;">
        ${idx + 1}. <a href="${safeUrl}" target="_blank" rel="noopener noreferrer" style="color: #2b6cb0; text-decoration: none;">${safeTitle}</a>
      </h3>
      <p style="font-size: 12px; color: #718096; margin-bottom: 12px;">Source: ${safeSource} | Published: ${escapeHtml(art.published_at)}</p>
      <p style="color: #4a5568; line-height: 1.6; margin-bottom: 12px;">${safeSummary}</p>
      <ul style="color: #4a5568; line-height: 1.5; padding-left: 20px; margin-bottom: 12px;">
        ${pointsList}
      </ul>
      <p style="margin: 0;">
        <a href="${safeUrl}" target="_blank" rel="noopener noreferrer" style="display: inline-block; font-size: 13px; font-weight: 600; color: #3182ce;">Read original source &rarr;</a>
      </p>
    </div>
  `;
});

const noteHtml = allArticles.length < 5
  ? `<p style="padding: 10px 14px; background: #feebc8; color: #744210; border-radius: 6px; font-size: 13px;"><strong>Notice:</strong> Only ${allArticles.length} valid articles were retrieved and processed for this topic today.</p>`
  : '';

const fullHtml = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background: #f7fafc; padding: 24px;">
  <div style="max-width: 680px; margin: 0 auto; background: #ffffff; border-radius: 10px; border: 1px solid #edf2f7; padding: 32px; box-shadow: 0 4px 6px rgba(0,0,0,0.02);">
    <div style="border-bottom: 2px solid #3182ce; padding-bottom: 16px; margin-bottom: 24px;">
      <h1 style="color: #2b6cb0; margin: 0 0 8px 0; font-size: 24px;">Daily AI Research Digest</h1>
      <p style="color: #718096; margin: 0; font-size: 14px;">Topic: <strong>${escapeHtml(topic)}</strong> | Generated on: ${dateStr}</p>
    </div>
    ${noteHtml}
    ${articlesHtml}
    <div style="border-top: 1px solid #edf2f7; padding-top: 16px; font-size: 12px; color: #a0aec0; text-align: center;">
      Automated via n8n & Google Gemini • Powered by Gemini Embeddings & Pinecone Vector Store
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    topic,
    date: dateStr,
    articles_processed: allArticles.length,
    summaries_stored: allArticles.length,
    digest_sent: true,
    html_body: fullHtml,
    articles: allArticles
  }
}];
